#include <iostream>
using namespace std;

int main() {
    cout << "How many scores? ";
    int count;
    cin >> count;

    for (int i = 1; i <= count; i++) {
        cout << "Score " << i << "? ";
        int score;
        cin >> score;

        cout << score << " | ";

        for (int star = 1; star <= score / 10; star++) {
            cout << "*";
        }

        cout << endl;
    }
    return 0;
}

